import numpy as np
from sklearn.linear_model import Ridge
from sklearn.model_selection import KFold

def paired_fold_diff(X, y, alpha_a, alpha_b, k, seed):
    diffs = []
    for tr, te in KFold(n_splits=k, shuffle=True, random_state=seed).split(X):
        mse = []
        for a in (alpha_a, alpha_b):
            model = Ridge(alpha=a).fit(X[tr], y[tr])
            mse.append(np.mean((model.predict(X[te]) - y[te]) ** 2))
        diffs.append(mse[0] - mse[1])
    return round(float(np.mean(diffs)), 4), round(float(np.std(diffs)), 4)
